def parse_duration(s):
    """
    Converts a duration string like '1h30m15s', '45s', '2h', '3m', '1h1s'
    into total seconds as an integer.

    Units must appear in the order: h, m, s.
    """
    total_seconds = 0
    current_number = ""

    for char in s:
        if char.isdigit():
            current_number += char
        else:
            if current_number:
                value = int(current_number)
                if char == 'h':
                    total_seconds += value * 3600
                elif char == 'm':
                    total_seconds += value * 60
                elif char == 's':
                    total_seconds += value
                current_number = ""

    return total_seconds
